using System.Reflection;
using System.Reflection.Metadata;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

/// <summary>Guards the layering: Domain and Application must not touch technical (I/O, network, ...) APIs or outer layers.</summary>
public sealed class LayerDependencyTests
{
    private static readonly string[] ForbiddenNamespacePrefixes =
    [
        "System.IO", "System.Net", "System.Data", "System.Diagnostics.Process",
        "System.Security.Cryptography", "System.Reflection", "System.Runtime.InteropServices",
        "Microsoft.Extensions", "Microsoft.AspNetCore", "Microsoft.EntityFrameworkCore",
    ];

    // Abstract types in System.IO that are harmless to reference are not allowed either; keep the rule simple.
    private static readonly Assembly Domain = typeof(Money).Assembly;
    private static readonly Assembly Application = typeof(AuthorizePayment).Assembly;
    private static readonly Assembly Infrastructure = typeof(FileSystemReceiptStore).Assembly;

    [Fact]
    public void Domain_depends_on_no_other_layer()
    {
        var offenders = ReferencedAssemblies(Domain)
            .Where(n => n.StartsWith("PaymentAuthorization.", StringComparison.Ordinal));

        Assert.Empty(offenders);
    }

    [Fact]
    public void Application_depends_only_on_Domain()
    {
        var offenders = ReferencedAssemblies(Application)
            .Where(n => n.StartsWith("PaymentAuthorization.", StringComparison.Ordinal))
            .Where(n => n != Domain.GetName().Name);

        Assert.Empty(offenders);
    }

    [Theory]
    [MemberData(nameof(InnerLayers))]
    public void Inner_layers_use_no_technical_APIs(string layer)
    {
        var assembly = layer == "Domain" ? Domain : Application;

        var offenders = ReferencedTypes(assembly)
            .Where(t => ForbiddenNamespacePrefixes.Any(p =>
                t.Namespace == p || t.Namespace.StartsWith(p + ".", StringComparison.Ordinal)))
            .Select(t => $"{t.Namespace}.{t.Name}")
            .Distinct()
            .Order();

        Assert.Empty(offenders);
    }

    [Fact]
    public void Layers_are_the_expected_assemblies()
    {
        Assert.NotEqual(Domain, Infrastructure);
        Assert.NotEqual(Application, Infrastructure);
    }

    public static TheoryData<string> InnerLayers() => ["Domain", "Application"];

    private static IEnumerable<string> ReferencedAssemblies(Assembly assembly) =>
        assembly.GetReferencedAssemblies().Select(a => a.Name!);

    private static IEnumerable<(string Namespace, string Name)> ReferencedTypes(Assembly assembly)
    {
        using var stream = File.OpenRead(assembly.Location);
        using var pe = new System.Reflection.PortableExecutable.PEReader(stream);
        var reader = pe.GetMetadataReader();

        foreach (var handle in reader.TypeReferences)
        {
            var type = reader.GetTypeReference(handle);
            yield return (reader.GetString(type.Namespace), reader.GetString(type.Name));
        }
    }
}
